   330	static exr_result_t
   331	extract_attr_chlist (
   332	    exr_context_t                     ctxt,
   333	    struct _internal_exr_seq_scratch* scratch,
   334	    exr_attr_chlist_t*                attrdata,
   335	    const char*                       aname,
   336	    const char*                       tname,
   337	    int32_t                           attrsz)
   338	{
   339	    char         chname[256];
   340	    int32_t      chlen;
   341	    int32_t      ptype, xsamp, ysamp;
   342	    uint8_t      flags[4];
   343	    int32_t      maxlen = ctxt->max_name_length;
   344	    exr_result_t rv;
   345	
   346	    rv = check_bad_attrsz (scratch, attrsz, 1, aname, tname, &chlen);
   347	
   348	    while (rv == EXR_ERR_SUCCESS && attrsz > 0)
   349	    {
   350	        chlen = 0;
   351	        rv    = read_text (chname, &chlen, maxlen, scratch, aname);
   352	        if (rv != EXR_ERR_SUCCESS) break;
   353	        attrsz -= chlen + 1;
   354	
   355	        if (chlen == 0) break;
   356	
   357	        if (attrsz < 16)
   358	        {
   359	            return ctxt->print_error (
   360	                ctxt,
   361	                EXR_ERR_ATTR_SIZE_MISMATCH,
   362	                "Out of data parsing '%s', last channel '%s'",
   363	                aname,
   364	                chname);
   365	        }
   366	
   367	        rv = scratch->sequential_read (scratch, &ptype, 4);
   368	        if (rv != EXR_ERR_SUCCESS) break;
   369	        rv = scratch->sequential_read (scratch, &flags, 4);
   370	        if (rv != EXR_ERR_SUCCESS) break;
   371	        rv = scratch->sequential_read (scratch, &xsamp, 4);
   372	        if (rv != EXR_ERR_SUCCESS) break;
   373	        rv = scratch->sequential_read (scratch, &ysamp, 4);
   374	        if (rv != EXR_ERR_SUCCESS) break;
   375	
   376	        attrsz -= 16;
   377	        ptype = (int32_t) one_to_native32 ((uint32_t) ptype);
   378	        xsamp = (int32_t) one_to_native32 ((uint32_t) xsamp);
   379	        ysamp = (int32_t) one_to_native32 ((uint32_t) ysamp);
   380	
   381	        rv = exr_attr_chlist_add_with_length (
   382	            ctxt,
   383	            attrdata,
   384	            chname,
   385	            chlen,
   386	            (exr_pixel_type_t) ptype,
   387	            flags[0],
   388	            xsamp,
   389	            ysamp);
   390	    }
   391	    return rv;
   392	}
